CREATE TABLE IF NOT EXISTS trade_campaign (campaign_id CHAR(36) PRIMARY KEY,name VARCHAR(255) NOT NULL,status VARCHAR(32) NOT NULL,current_stage VARCHAR(64) NOT NULL,version INT NOT NULL DEFAULT 1,paused TINYINT(1) NOT NULL DEFAULT 0,created_by VARCHAR(128) NOT NULL,created_at DATETIME(6) NOT NULL,updated_at DATETIME(6) NOT NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS trade_stage_run (run_id CHAR(36) PRIMARY KEY,campaign_id CHAR(36) NOT NULL,stage VARCHAR(64) NOT NULL,version INT NOT NULL,status VARCHAR(32) NOT NULL,result_json JSON NOT NULL,evidence_json JSON NOT NULL,risks_json JSON NOT NULL,missing_inputs_json JSON NOT NULL,next_stage VARCHAR(64),next_required_inputs_json JSON NOT NULL,human_review_required TINYINT(1) NOT NULL,input_hash CHAR(64) NOT NULL,output_hash CHAR(64),error_code VARCHAR(96),started_at DATETIME(6) NOT NULL,completed_at DATETIME(6),UNIQUE KEY uk_trade_stage_version(campaign_id,stage,version),CONSTRAINT fk_trade_stage_campaign FOREIGN KEY(campaign_id) REFERENCES trade_campaign(campaign_id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS trade_stage_job (job_id CHAR(36) PRIMARY KEY,campaign_id CHAR(36) NOT NULL,stage VARCHAR(64) NOT NULL,input_json JSON NOT NULL,business_key VARCHAR(255) NOT NULL,status VARCHAR(32) NOT NULL,lease_owner VARCHAR(128),lease_until DATETIME(6),attempt_count INT NOT NULL DEFAULT 0,next_attempt_at DATETIME(6),error_code VARCHAR(96),created_at DATETIME(6) NOT NULL,updated_at DATETIME(6) NOT NULL,UNIQUE KEY uk_trade_job_business(business_key),KEY ix_trade_job_claim(status,next_attempt_at,lease_until,created_at),CONSTRAINT fk_trade_job_campaign FOREIGN KEY(campaign_id) REFERENCES trade_campaign(campaign_id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS trade_input_snapshot (snapshot_id CHAR(36) PRIMARY KEY,campaign_id CHAR(36) NOT NULL,input_type VARCHAR(64) NOT NULL,version INT NOT NULL,payload_json JSON NOT NULL,payload_hash CHAR(64) NOT NULL,source_name VARCHAR(255),created_at DATETIME(6) NOT NULL,UNIQUE KEY uk_trade_input_version(campaign_id,input_type,version),CONSTRAINT fk_trade_input_campaign FOREIGN KEY(campaign_id) REFERENCES trade_campaign(campaign_id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS trade_evidence (evidence_id CHAR(36) PRIMARY KEY,campaign_id CHAR(36) NOT NULL,stage VARCHAR(64) NOT NULL,source_type VARCHAR(32) NOT NULL,source_ref TEXT NOT NULL,fetched_at DATETIME(6) NOT NULL,content_hash CHAR(64) NOT NULL,excerpt TEXT NOT NULL,created_at DATETIME(6) NOT NULL,KEY ix_trade_evidence_campaign(campaign_id,stage),CONSTRAINT fk_trade_evidence_campaign FOREIGN KEY(campaign_id) REFERENCES trade_campaign(campaign_id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS trade_product_profile (sku VARCHAR(64) PRIMARY KEY,product_size VARCHAR(255),packing_size VARCHAR(255),weight_kg DECIMAL(20,6),hs_code VARCHAR(32),certifications_json JSON NOT NULL,materials_json JSON NOT NULL,applications_json JSON NOT NULL,source_kind VARCHAR(32) NOT NULL,source_ref TEXT,version INT NOT NULL DEFAULT 1,updated_at DATETIME(6) NOT NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS trade_price_rule (rule_id CHAR(36) PRIMARY KEY,sku VARCHAR(64) NOT NULL,min_qty DECIMAL(20,6) NOT NULL,max_qty DECIMAL(20,6),unit_price DECIMAL(20,6) NOT NULL,currency CHAR(3) NOT NULL,incoterm VARCHAR(16) NOT NULL,payment_terms VARCHAR(255) NOT NULL,valid_from DATETIME(6) NOT NULL,valid_until DATETIME(6) NOT NULL,approval_status VARCHAR(32) NOT NULL,version INT NOT NULL DEFAULT 1,source_ref TEXT NOT NULL,UNIQUE KEY uk_trade_price_version(sku,min_qty,currency,incoterm,version)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS trade_prospect (prospect_id CHAR(36) PRIMARY KEY,campaign_id CHAR(36) NOT NULL,company_name VARCHAR(255) NOT NULL,normalized_domain VARCHAR(255),website TEXT,country VARCHAR(128),business_type VARCHAR(64),source_urls_json JSON NOT NULL,source_notes_json JSON NOT NULL,contact_email VARCHAR(320) NOT NULL,contact_phone VARCHAR(64) NOT NULL,email_result VARCHAR(32) NOT NULL,phone_result VARCHAR(32) NOT NULL,do_not_contact TINYINT(1) NOT NULL DEFAULT 0,status VARCHAR(32) NOT NULL,created_at DATETIME(6) NOT NULL,updated_at DATETIME(6) NOT NULL,UNIQUE KEY uk_trade_prospect_domain(campaign_id,normalized_domain),CONSTRAINT fk_trade_prospect_campaign FOREIGN KEY(campaign_id) REFERENCES trade_campaign(campaign_id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS trade_outreach_draft (draft_id CHAR(36) PRIMARY KEY,campaign_id CHAR(36) NOT NULL,prospect_id CHAR(36) NOT NULL,version INT NOT NULL,subject TEXT NOT NULL,body TEXT NOT NULL,content_hash CHAR(64) NOT NULL,status VARCHAR(32) NOT NULL,approved_by VARCHAR(128),approved_at DATETIME(6),created_at DATETIME(6) NOT NULL,UNIQUE KEY uk_trade_draft_version(prospect_id,version),CONSTRAINT fk_trade_draft_campaign FOREIGN KEY(campaign_id) REFERENCES trade_campaign(campaign_id),CONSTRAINT fk_trade_draft_prospect FOREIGN KEY(prospect_id) REFERENCES trade_prospect(prospect_id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS trade_outreach_outbox (command_id CHAR(36) PRIMARY KEY,draft_id CHAR(36) NOT NULL,draft_version INT NOT NULL,content_hash CHAR(64) NOT NULL,account_id VARCHAR(128) NOT NULL,recipient VARCHAR(320) NOT NULL,status VARCHAR(32) NOT NULL,lease_owner VARCHAR(128),lease_until DATETIME(6),attempt_count INT NOT NULL DEFAULT 0,max_attempts INT NOT NULL DEFAULT 5,next_attempt_at DATETIME(6),smtp_message_id VARCHAR(255),accepted_at DATETIME(6),error_code VARCHAR(96),created_at DATETIME(6) NOT NULL,updated_at DATETIME(6) NOT NULL,UNIQUE KEY uk_trade_outbox_draft(draft_id,draft_version),KEY ix_trade_outreach_claim(status,next_attempt_at,lease_until,created_at),CONSTRAINT fk_trade_outbox_draft FOREIGN KEY(draft_id) REFERENCES trade_outreach_draft(draft_id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS trade_quote_draft (quote_draft_id CHAR(36) PRIMARY KEY,campaign_id CHAR(36) NOT NULL,prospect_id CHAR(36),version INT NOT NULL,quotation_number VARCHAR(96) NOT NULL,payload_json JSON NOT NULL,content_hash CHAR(64) NOT NULL,status VARCHAR(32) NOT NULL,artifact_dir TEXT,approved_by VARCHAR(128),approved_at DATETIME(6),created_at DATETIME(6) NOT NULL,UNIQUE KEY uk_trade_quote_version(campaign_id,quotation_number,version),CONSTRAINT fk_trade_quote_campaign FOREIGN KEY(campaign_id) REFERENCES trade_campaign(campaign_id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS trade_artifact (artifact_id CHAR(36) PRIMARY KEY,campaign_id CHAR(36) NOT NULL,object_type VARCHAR(32) NOT NULL,object_id CHAR(36) NOT NULL,object_version INT NOT NULL,artifact_kind VARCHAR(32) NOT NULL,file_name VARCHAR(255) NOT NULL,storage_path TEXT NOT NULL,byte_size BIGINT NOT NULL,artifact_sha256 CHAR(64) NOT NULL,created_at DATETIME(6) NOT NULL,UNIQUE KEY uk_trade_artifact_object(object_type,object_id,object_version,artifact_kind),KEY ix_trade_artifact_object(object_type,object_id,object_version),CONSTRAINT fk_trade_artifact_campaign FOREIGN KEY(campaign_id) REFERENCES trade_campaign(campaign_id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS trade_ai_audit (audit_id CHAR(36) PRIMARY KEY,campaign_id CHAR(36),stage VARCHAR(64) NOT NULL,provider_type VARCHAR(32) NOT NULL,model VARCHAR(128) NOT NULL,prompt_version VARCHAR(64) NOT NULL,input_hash CHAR(64) NOT NULL,output_hash CHAR(64),duration_ms BIGINT,status VARCHAR(32) NOT NULL,actor_id VARCHAR(128) NOT NULL,created_at DATETIME(6) NOT NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS trade_audit_event (audit_id CHAR(36) PRIMARY KEY,campaign_id CHAR(36),actor_id VARCHAR(128) NOT NULL,action VARCHAR(96) NOT NULL,object_type VARCHAR(64) NOT NULL,object_id VARCHAR(128) NOT NULL,result VARCHAR(32) NOT NULL,metadata_json JSON NOT NULL,occurred_at DATETIME(6) NOT NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS trade_idempotency (scope VARCHAR(255) NOT NULL,idempotency_key VARCHAR(255) NOT NULL,payload_hash CHAR(64) NOT NULL,response_json JSON NOT NULL,created_at DATETIME(6) NOT NULL,PRIMARY KEY(scope,idempotency_key)) ENGINE=InnoDB;
